package dev.emi.emi.registry;import dev.emi.emi.api.stack.*;import java.util.*;public class EmiStackList {public static class ComparisonHashStrategy implements it.unimi.dsi.fastutil.Hash.Strategy<EmiStack>{public int hashCode(EmiStack s){return Objects.hash(s.getKey(),s.getNbt());}public boolean equals(EmiStack a,EmiStack b){return a==b||a!=null&&b!=null&&a.getKey()==b.getKey()&&Objects.equals(a.getNbt(),b.getNbt());}}}
